import rawEngines from "../../../shared/data/engines.json";
import type { EngineManifest } from "../types/engine";

/**
 * Engine manifests are generated by `node scripts/build-engines.mjs`, which
 * compiles every Rust engine to WASM, copies the binaries into
 * `frontend/public/engines/<dir>/<version>/` and records the SHA-256 hash and
 * size in `shared/data/engines.json`. The backend reads the same file, so the
 * two registries can never drift.
 */
export const BUILTIN_ENGINES: Record<string, EngineManifest> = Object.fromEntries(
  (rawEngines as { engines: any[] }).engines.map((e) => [
    e.id,
    {
      id: e.id,
      name: e.name,
      version: e.version,
      type: e.type,
      url: e.url,
      glue: e.glue,
      worker: e.worker,
      hash: e.hash,
      size: e.size,
      capabilities: e.capabilities ?? [],
      dependencies: e.dependencies ?? [],
    } satisfies EngineManifest,
  ]),
);

export function getEngineManifest(id: string): EngineManifest | undefined {
  return BUILTIN_ENGINES[id];
}

export function listEngines(): EngineManifest[] {
  return Object.values(BUILTIN_ENGINES);
}
